package cn.sixnine.filmlog;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;

/** Shared alignment for the confirmed library, equipment, inventory and statistics pages. */
final class LibraryUi {
    static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
    static TextView text(Context c,String value,int sp,int color){TextView v=new TextView(c);v.setText(value);v.setTextSize(sp);v.setTextColor(color);v.setIncludeFontPadding(false);return v;}
    static LinearLayout column(Context c){LinearLayout v=new LinearLayout(c);v.setOrientation(1);return v;}
    static GradientDrawable surface(Context c,int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,radius));return d;}
    static Button icon(Context c,int code,String description,Runnable action){Button v=new Button(c);v.setText(String.valueOf((char)code));v.setTypeface(Typeface.createFromAsset(c.getAssets(),"fonts/Phosphor.ttf"));v.setTextSize(android.util.TypedValue.COMPLEX_UNIT_DIP,22);v.setContentDescription(description);v.setTextColor(c.getColor(R.color.ui_accent));v.setPadding(0,0,0,0);v.setIncludeFontPadding(false);v.setGravity(Gravity.CENTER);v.setMinWidth(0);v.setMinimumWidth(0);v.setMinHeight(0);v.setMinimumHeight(0);v.setStateListAnimator(null);v.setElevation(0);v.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(c.getColor(R.color.ui_selected)),null,null));v.setOnClickListener(w->action.run());return v;}
    static Button action(Context c,String label,boolean primary,Runnable action){Button b=new Button(c);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(c.getColor(primary?R.color.ui_on_accent:R.color.ui_accent));b.setStateListAnimator(null);b.setElevation(0);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(c,46));b.setMinimumHeight(dp(c,46));b.setPadding(dp(c,12),dp(c,8),dp(c,12),dp(c,8));GradientDrawable bg=surface(c,c.getColor(primary?R.color.ui_accent:R.color.ui_card),7);if(!primary)bg.setStroke(dp(c,1),c.getColor(R.color.ui_outline));b.setBackground(bg);b.setOnClickListener(v->action.run());return b;}
    static View header(Context c,CharSequence title,Runnable back,View right){return header(c,title,back,right,0);}
    static View header(Context c,CharSequence title,Runnable back,View right,int inset){FrameLayout bar=new FrameLayout(c);bar.setTag("library-header");bar.setMinimumHeight(dp(c,56));TextView h=text(c,title.toString(),17,c.getColor(R.color.ui_ink));h.setText(title);h.setMaxLines(2);h.setEllipsize(android.text.TextUtils.TruncateAt.END);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.setGravity(Gravity.CENTER);h.setTag("library-header-title");FrameLayout.LayoutParams middle=new FrameLayout.LayoutParams(-1,-1);middle.leftMargin=middle.rightMargin=dp(c,56);bar.addView(h,middle);bar.addView(icon(c,0xe138,"返回",back),new FrameLayout.LayoutParams(dp(c,48),dp(c,56),Gravity.LEFT));if(right!=null)bar.addView(right,new FrameLayout.LayoutParams(dp(c,48),dp(c,56),Gravity.RIGHT));LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(-1,dp(c,56));size.leftMargin=size.rightMargin=-dp(c,inset);bar.setLayoutParams(size);return bar;}
    static LinearLayout tabs(Context c,String[] labels,int selected,java.util.function.IntConsumer action){LinearLayout row=new LinearLayout(c);for(int i=0;i<labels.length;i++){final int index=i;LinearLayout cell=column(c);TextView label=text(c,labels[i],14,c.getColor(i==selected?R.color.ui_accent:R.color.ui_muted));label.setGravity(Gravity.CENTER);label.setTypeface(Typeface.DEFAULT,i==selected?Typeface.BOLD:Typeface.NORMAL);cell.addView(label,new LinearLayout.LayoutParams(-1,dp(c,44)));View underline=new View(c);underline.setBackgroundColor(i==selected?c.getColor(R.color.ui_accent):Color.TRANSPARENT);cell.addView(underline,new LinearLayout.LayoutParams(-1,dp(c,2)));cell.setSelected(i==selected);cell.setFocusable(true);cell.setContentDescription(labels[i]+(i==selected?"，已选择":""));cell.setOnClickListener(v->action.accept(index));row.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}return row;}
    static void line(Context c,LinearLayout parent){View line=new View(c);line.setBackgroundColor(c.getColor(R.color.ui_outline));parent.addView(line,new LinearLayout.LayoutParams(-1,dp(c,1)));}
    static void fact(Context c,LinearLayout parent,String label,String value){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.TOP);row.setPadding(0,dp(c,11),0,dp(c,11));TextView key=text(c,label,12,c.getColor(R.color.ui_muted));TextView val=text(c,value,13,c.getColor(R.color.ui_ink));val.setGravity(Gravity.RIGHT);row.addView(key,new LinearLayout.LayoutParams(-2,-2));LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(0,-2,1);size.leftMargin=dp(c,18);row.addView(val,size);parent.addView(row);line(c,parent);}
    static Dialog sheet(Activity a,String title,LinearLayout content,View footer){Dialog d=new Dialog(a);LinearLayout body=column(a);body.setBackground(surface(a,a.getColor(R.color.ui_background),16));LinearLayout head=new LinearLayout(a);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(a,16),0,dp(a,8),0);TextView h=text(a,title,17,a.getColor(R.color.ui_ink));h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.setGravity(Gravity.CENTER_VERTICAL);head.addView(h,new LinearLayout.LayoutParams(0,dp(a,56),1));head.addView(icon(a,0xe4f6,"关闭",d::cancel),new LinearLayout.LayoutParams(dp(a,44),dp(a,44)));body.addView(head);ScrollView scroll=new ScrollView(a){@Override protected void onMeasure(int width,int height){int maximum=Math.max(dp(a,120),Math.min(dp(a,500),(int)(a.getResources().getDisplayMetrics().heightPixels*.84f)-dp(a,footer==null?70:150)));int available=View.MeasureSpec.getMode(height)==View.MeasureSpec.UNSPECIFIED?maximum:Math.min(maximum,View.MeasureSpec.getSize(height));super.onMeasure(width,View.MeasureSpec.makeMeasureSpec(available,View.MeasureSpec.AT_MOST));}};scroll.setFillViewport(false);scroll.addView(content);body.addView(scroll,new LinearLayout.LayoutParams(-1,-2));if(footer!=null){LinearLayout actions=column(a);actions.setPadding(dp(a,16),dp(a,10),dp(a,16),dp(a,16));actions.addView(footer);body.addView(actions);}d.setContentView(body);Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);w.setDimAmount(.45f);w.setGravity(Gravity.BOTTOM);w.setLayout(-1,-2);}d.show();if(w!=null)w.setLayout(-1,-2);return d;}
}
